"""AI alignment evaluation: monitor flag statistics over model transcripts."""

_FLAG_VALUES = {"1": True, "0": False, "": None}


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for n, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = [f.strip() for f in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {n}: expected 3 fields, got {len(fields)}")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError:
            raise ValueError(f"line {n}: day is not an integer: {day!r}") from None
        if flag not in _FLAG_VALUES:
            raise ValueError(f"line {n}: flagged must be 1, 0 or empty, got {flag!r}")
        out.append({"id": id_, "day": day, "flagged": _FLAG_VALUES[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts, keeping the last per id. See SPEC.md section 5."""
    latest = {}
    for e in events:
        latest[e["id"]] = e
    return sorted(latest.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []
    counts = [0] * (end_day - start_day + 1)
    for e in events:
        if e["flagged"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts
